"""The images probes run on: generated by code, so identical every run and owned by no one."""

from __future__ import annotations

import colorsys

import numpy as np

from scripts.adobe_observed_truth.test_images import CHART_REGIONS, chart, icon


def test_the_chart_is_pixel_for_pixel_the_same_every_time() -> None:
    assert chart().tobytes() == chart().tobytes()


def test_the_chart_spans_black_to_white_in_every_channel() -> None:
    rgb = np.asarray(chart())[..., :3]

    assert [(int(rgb[..., c].min()), int(rgb[..., c].max())) for c in range(3)] == [(0, 255)] * 3


def test_the_chart_holds_at_least_twelve_distinct_saturated_hues() -> None:
    pixels = np.asarray(chart())[..., :3].reshape(-1, 3) / 255
    hues = {
        round(h * 12) % 12
        for r, g, b in np.unique(pixels, axis=0)
        for h, s, v in [colorsys.rgb_to_hsv(r, g, b)]
        if s > 0.8 and v > 0.8
    }

    assert len(hues) == 12


def test_the_chart_has_hard_black_to_white_edges_for_blur_and_sharpen() -> None:
    grey = np.asarray(chart().convert("L")).astype(int)

    assert np.abs(np.diff(grey, axis=1)).max() == 255


def test_part_of_the_chart_is_transparent_for_the_layer_and_alpha_tools() -> None:
    alpha = np.asarray(chart())[..., 3]

    assert (int(alpha.min()), int(alpha.max())) == (0, 255)


def test_the_named_chart_regions_cover_every_pixel_exactly_once() -> None:
    covered = np.zeros(np.asarray(chart()).shape[:2], dtype=int)
    for y0, y1, x0, x1 in CHART_REGIONS.values():
        covered[y0:y1, x0:x1] += 1

    assert (int(covered.min()), int(covered.max())) == (1, 1)


def test_the_icon_ships_with_the_harness_and_is_scaled_to_fit_600_pixels_keeping_its_transparency() -> None:
    image = icon()
    alpha = np.asarray(image)[..., 3]

    assert (image.mode, max(image.size) == 600, int(alpha.min()), int(alpha.max())) == (
        "RGBA", True, 0, 255
    )